HORAS_DE_PLAZO = 2


def poner_plazo(apps, schema_editor):
    """Las compras directas pendientes no tenían plazo y sus obras quedaban reservadas para siempre.
    Se les pone el plazo contado desde su creación: las que ya vencieron se liberan en la siguiente corrida
    de expire_unpaid_direct_orders."""
    Order = apps.get_model("marketplace", "Order")
    pendientes = Order.objects.filter(order_type="COMPRA_DIRECTA", status="PENDIENTE", payment_due_at__isnull=True)
